```python
# 创建集合
fruits = {'apple', 'banana', 'orange'}
print(fruits)  # 输出顺序可能不同，例如 {'orange', 'apple', 'banana'}

# 添加元素
fruits.add('grape')
fruits.add('apple')  # 重复添加无效
print(fruits)  # {'orange', 'apple', 'banana', 'grape'}

# 删除元素
fruits.remove('banana')  # 存在则删除
# fruits.remove('pear')  # 如果不存在会报KeyError
fruits.discard('pear')   # 不存在也不报错

# 成员检查
print('apple' in fruits)  # True
print('pear' not in fruits)  # True

# 集合运算
A = {1, 2, 3, 4}
B = {3, 4, 5, 6}
print(A | B)  # 并集 {1,2,3,4,5,6}
print(A & B)  # 交集 {3,4}
print(A - B)  # 差集 {1,2}
print(A ^ B)  # 对称差集 {1,2,5,6}

# 去重应用
numbers = [1, 2, 2, 3, 3, 4]
unique = list(set(numbers))  # [1,2,3,4] 注意顺序可能改变
```
